"use client";

import { useMemo, useRef, useEffect, useState } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";

// Custom shader for the liquid particle field
const vertexShader = `
  uniform float uTime;
  uniform vec2 uMouse;
  uniform int uScene;
  uniform float uTransition;
  
  attribute float size;
  
  varying float vAlpha;
  
  // Classic 3D noise function snippet could go here, 
  // but for performance, we'll use sine waves combined for organic flow
  
  void main() {
    vec3 pos = position;
    
    // Base organic wave using sine - reduced amplitude for subtlety
    float wave = sin(pos.x * 0.05 + uTime * 0.2) * cos(pos.y * 0.05 + uTime * 0.1) * 3.0;
    
    // Mouse repulsion
    vec2 mouseWorld = uMouse * 100.0; // Scale approx to world size
    float distToMouse = distance(pos.xy, mouseWorld);
    float repulsion = 0.0;
    if(distToMouse < 40.0) {
      repulsion = (40.0 - distToMouse) * 0.2; // Softer repulsion
    }
    
    // Scene-specific behavior (all made much more subtle)
    if (uScene == 0) {
      // Normal slow wave
    } else if (uScene == 1) {
      // Ripple (More attention)
      float ripple = sin(distToMouse * 0.3 - uTime * 3.0) * 2.0;
      wave += ripple * smoothstep(50.0, 0.0, distToMouse);
    } else if (uScene == 2) {
      // Expand (More impact)
      pos.xy *= 1.0 + sin(uTime * 0.5) * 0.05;
    } else if (uScene == 3) {
      // Fast wave (More connection)
      wave = sin(pos.x * 0.1 + uTime * 0.5) * cos(pos.y * 0.1 + uTime * 0.5) * 6.0;
    } else if (uScene == 4) {
      // Converge (More growth)
      vec2 center = vec2(0.0);
      float dist = distance(pos.xy, center);
      pos.xy -= normalize(pos.xy) * sin(uTime * 0.5) * min(dist, 3.0);
    } else if (uScene >= 9) {
      // Organize and converge softly
      vec2 center = vec2(0.0);
      pos.xy = mix(pos.xy, center, 0.05); 
    }
    
    pos.z += wave + repulsion;
    
    // Final liquid transition distortion
    if (uTransition > 0.0) {
      // Pull to center then explode
      vec2 center = vec2(0.0);
      float distToCenter = distance(pos.xy, center);
      
      if (uTransition < 0.5) {
        // Phase 1: Pull in
        float pull = smoothstep(0.0, 0.5, uTransition);
        pos.xy = mix(pos.xy, center, pull * 0.8);
      } else {
        // Phase 2: Explode outward and ripple Z
        float exp = smoothstep(0.5, 1.0, uTransition);
        pos.xy += normalize(pos.xy) * exp * 150.0;
        pos.z += sin(distToCenter * 0.2 - uTime * 10.0) * exp * 50.0;
      }
    }
    
    vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
    
    // Perspective sizing
    gl_PointSize = size * (200.0 / -mvPosition.z);
    
    // Fade alpha based on Z depth
    vAlpha = smoothstep(-20.0, 20.0, pos.z) * 0.5 + 0.2;
    
    // Transition fade out
    if (uTransition > 0.5) {
      vAlpha *= 1.0 - smoothstep(0.5, 1.0, uTransition);
    }
    
    gl_Position = projectionMatrix * mvPosition;
  }
`;

const fragmentShader = `
  varying float vAlpha;
  
  void main() {
    // Make circular particles
    vec2 xy = gl_PointCoord.xy - vec2(0.5);
    float ll = length(xy);
    if (ll > 0.5) discard;
    
    // Soft edge
    float a = (0.5 - ll) * 2.0 * vAlpha;
    
    // Almost white with a tiny tint (subtle opacity)
    gl_FragColor = vec4(1.0, 0.95, 0.9, a * 0.4);
  }
`;

function Particles({ sceneIndex, transitionProgress, mousePos }: { sceneIndex: number, transitionProgress: number, mousePos: React.MutableRefObject<[number, number]> }) {
  const { size, viewport } = useThree();
  const materialRef = useRef<THREE.ShaderMaterial>(null);
  
  // Responsive particle count
  const particleCount = useMemo(() => {
    if (size.width < 768) return 3000;
    return 8000;
  }, [size.width]);

  const [positions, sizes] = useMemo(() => {
    const positions = new Float32Array(particleCount * 3);
    const sizes = new Float32Array(particleCount);
    
    // Scatter particles across a wide plane
    for (let i = 0; i < particleCount; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 300; // X
      positions[i * 3 + 1] = (Math.random() - 0.5) * 200; // Y
      positions[i * 3 + 2] = (Math.random() - 0.5) * 20; // Z
      
      sizes[i] = Math.random() * 2.0 + 1.0;
    }
    
    return [positions, sizes];
  }, [particleCount]);

  useFrame((state) => {
    if (materialRef.current) {
      materialRef.current.uniforms.uTime.value = state.clock.elapsedTime;
      
      // Target mouse position smoothly
      const currentMouse = materialRef.current.uniforms.uMouse.value;
      currentMouse.x += (mousePos.current[0] - currentMouse.x) * 0.1;
      currentMouse.y += (mousePos.current[1] - currentMouse.y) * 0.1;
      
      materialRef.current.uniforms.uScene.value = sceneIndex;
      materialRef.current.uniforms.uTransition.value = transitionProgress;
    }
  });

  return (
    <points>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={particleCount}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-size"
          count={particleCount}
          array={sizes}
          itemSize={1}
        />
      </bufferGeometry>
      <shaderMaterial
        ref={materialRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        transparent
        depthWrite={false}
        blending={THREE.AdditiveBlending}
        uniforms={{
          uTime: { value: 0 },
          uMouse: { value: new THREE.Vector2(0, 0) },
          uScene: { value: 0 },
          uTransition: { value: 0 }
        }}
      />
    </points>
  );
}

export default function ParticleField({ sceneIndex, transitionProgress }: { sceneIndex: number, transitionProgress: number }) {
  const mousePos = useRef<[number, number]>([0, 0]);

  // Track normalized mouse position
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      // Normalize to -1 to 1
      mousePos.current[0] = (e.clientX / window.innerWidth) * 2 - 1;
      mousePos.current[1] = -(e.clientY / window.innerHeight) * 2 + 1;
    };
    
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div style={{ position: 'absolute', top: 0, left: 0, width: '100vw', height: '100vh', zIndex: 1, pointerEvents: 'none' }}>
      <Canvas camera={{ position: [0, 0, 80], fov: 45 }} dpr={[1, 2]}>
        <Particles sceneIndex={sceneIndex} transitionProgress={transitionProgress} mousePos={mousePos} />
      </Canvas>
    </div>
  );
}
